rows=[]
def add(cid,pn,anchor,new,reason='Remove publication-history framing while preserving the mathematical scope.',category='prose',occurrence=0):
    p=D[cid][pn-1];bs=[b for b in p.get_text('blocks') if anchor in b[4]]
    assert len(bs)>occurrence,(cid,pn,anchor,len(bs))
    b=bs[occurrence]
    if any(x['component_id']==cid and x['source_page_1based']==pn and x['bbox']==list(b[:4]) for x in rows):raise ValueError(('duplicate block',cid,pn,anchor))
    rows.append({'component_id':cid,'source_page_1based':pn,'book_page_before':C[cid]['book_pages'].get(str(pn-1),-1)+1,'old':b[4].rstrip('\n'),'new':new,'bbox':list(b[:4]),'context':anchor,'reason':reason,'category':category,'source_path_hint':C[cid]['path'],'action':'replace_block' if new else 'remove_block'})
def lines(cid,pattern,reason):
    for pn in C[cid]['keep_pages']:
      for b in D[cid][pn].get_text('dict')['blocks']:
       for l in b.get('lines',[]):
        t=''.join(s['text'] for s in l['spans'])
        if re.fullmatch(pattern,t):rows.append({'component_id':cid,'source_page_1based':pn+1,'book_page_before':C[cid]['book_pages'][str(pn)]+1,'old':t,'new':'','bbox':list(l['bbox']),'context':'Source catalogue metadata, separate from declaration text and hypotheses.','reason':reason,'category':'production_metadata','source_path_hint':C[cid]['path'],'action':'remove_line'})
